import sys
import heapq

def bfs(start_x, start_y, target_x, target_y, vis):
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    heap = []
    heapq.heappush(heap, (0, start_x, start_y))
    vis[start_x][start_y] = 1
    while heap:
        step, x, y = heapq.heappop(heap)
        if x == target_x and y == target_y:
            return step
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if nx < 0 or ny < 0 or nx >= 110 or ny >= 110:
                continue
            if vis[nx][ny]:
                continue
            vis[nx][ny] = 1
            heapq.heappush(heap, (step + 1, nx, ny))
    return -1  # Should not happen

def main():
    s = sys.stdin.readline().strip()
    length = len(s)
    x = y = 0
    min_x = min_y = 0
    for ch in s:
        if ch == 'L':
            y -= 1
        elif ch == 'R':
            y += 1
        elif ch == 'U':
            x -= 1
        elif ch == 'D':
            x += 1
        min_x = min(min_x, x)
        min_y = min(min_y, y)
    offset_x = -min_x
    offset_y = -min_y

    vis = [[1] * 110 for _ in range(110)]
    x, y = offset_x, offset_y
    for ch in s:
        if ch == 'L':
            y -= 1
        elif ch == 'R':
            y += 1
        elif ch == 'U':
            x -= 1
        elif ch == 'D':
            x += 1
        vis[x][y] = 0

    ans = bfs(offset_x, offset_y, x, y, vis)
    if ans == length:
        print("OK")
    else:
        print("BUG")

if __name__ == "__main__":
    main()

